use imajev_carry_planes_bench::Measurement;
fn main(){let a:Vec<_>=std::env::args().collect();match a[1].as_str(){"query"=>{let bytes=std::fs::read(&a[2]).unwrap();let args=candid::encode_args((bytes,a[3].parse::<u32>().unwrap(),a[4].parse::<u32>().unwrap(),a[5].parse::<bool>().unwrap())).unwrap();std::fs::write(&a[6],args).unwrap();},"decode"=>{let hex=std::fs::read_to_string(&a[2]).unwrap();let s=hex.trim();let bytes:Vec<_>=s.as_bytes().chunks_exact(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).unwrap(),16).unwrap()).collect();let r:candid::Result<(Measurement,)>=candid::decode_args(&bytes);println!("{}",serde_json::to_string(&r.unwrap().0).unwrap());},_=>panic!("args")}}
